corrected_code:
package docroutes

import (
	"net/http"

	"github.com/gin-gonic/gin"
	"myapp/auth"
	"myapp/docs"
)

func SetupDocStorageRoutes(r *gin.Engine, store docs.StorageService) {
	secured := r.Group("/api")
	secured.Use(auth.TokenAuthMiddleware())

	secured.DELETE("/documents/:docName", func(c *gin.Context) {
		docName := c.Param("docName")
		orgID := c.GetString("org_id")

		if err := store.DeleteDocumentForOrg(c.Request.Context(), docName, orgID); err != nil {
			c.JSON(http.StatusNotFound, gin.H{"error": "Document not found or unauthorized"})
			return
		}
		c.Status(http.StatusNoContent)
	})
}
